"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$zipPath = '"'C:\\Users\\hzq00\\Downloads\\HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE.zip'
"'$prefix = '"'HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE/'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
"'$expected = @{}
$sumsText = & tar -xOf $zipPath ($prefix + '"'SHA256SUMS')
foreach ("'$line in $sumsText) {
  if ($line -match '"'"'^'"\\s*([0-9a-fA-F]{64})\\s+(.+?)\\s*"'$'"') {
    "'$expected[$matches[2].Trim()] = $matches[1].ToLower()
  }
}
$zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
try {
  $results = @()
  foreach ($e in $zip.Entries) {
    $rel = $e.FullName
    if ($rel.StartsWith($prefix)) { $rel = $rel.Substring($prefix.Length) }
    if ($rel -eq '"'SHA256SUMS') { continue }
    "'$sha = [System.Security.Cryptography.SHA256]::Create()
    $s = $e.Open()
    try { $hash = ($sha.ComputeHash($s) | ForEach-Object { $_.ToString('"'x2') }) -join '' } finally { "'$s.Dispose() }
    $exp = $expected[$rel]
    if ($null -eq $exp) { $status = '"'NOT_LISTED_IN_SHA256SUMS' }
    elseif ("'$hash -eq $exp) { $status = '"'MATCH' } else { "'$status = '"'MISMATCH' }
    "'$results += [PSCustomObject]@{ Entry = $rel; Expected = $exp; Computed = $hash; Status = $status }
  }
  $results | Format-Table -AutoSize
  '"'---SUMMARY---'
  'SHA256SUMS entries: ' + "'$expected.Count
  '"'ZIP entries checked: ' + "'$results.Count
  '"'MATCH: ' + ("'$results | Where-Object Status -eq '"'MATCH').Count
  'MISMATCH: ' + ("'$results | Where-Object Status -eq '"'MISMATCH').Count
  'NOT_LISTED_IN_SHA256SUMS: ' + ("'$results | Where-Object Status -eq '"'NOT_LISTED_IN_SHA256SUMS').Count
  'Unmatched expected (in SUMS but not checked): ' + (@("'$expected.Keys | Where-Object { $relCheck = $_; -not ($results | Where-Object Entry -eq $relCheck) }).Count)
} finally { $zip.Dispose() }'

